import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        if (n <= 0 || n > 11) {
            out.println(0);
            out.close();
            return;
        }
        int[][] p = new int[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                p[i][j] = in.nextInt();
            }
        }
        List<Integer> good = IntStream.range(0, n)
                .filter(i -> isGood(p, i))
                .mapToObj(i -> i + 1)
                .collect(Collectors.toList());
        if (good.isEmpty()) {
            out.println(0);
        } else {
            out.println(good.size());
            for (int idx : good) {
                out.println(idx);
            }
        }
        out.close();
    }

    static boolean isGood(int[][] p, int i) {
        for (int j = 0; j < p.length; j++) {
            for (int k = 0; k < p.length; k++) {
                if (i != j && i != k && j != k) {
                    int[] u = sub(p[j], p[i]);
                    int[] v = sub(p[k], p[i]);
                    if (angle(u, v)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    static int[] sub(int[] a, int[] b) {
        return new int[]{a[0]-b[0], a[1]-b[1], a[2]-b[2], a[3]-b[3], a[4]-b[4]};
    }

    static boolean angle(int[] u, int[] v) {
        int dot = u[0]*v[0] + u[1]*v[1] + u[2]*v[2] + u[3]*v[3] + u[4]*v[4];
        double mu = Math.sqrt(u[0]*u[0] + u[1]*u[1] + u[2]*u[2] + u[3]*u[3] + u[4]*u[4]);
        double mv = Math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2] + v[3]*v[3] + v[4]*v[4]);
        return Math.toDegrees(Math.acos(dot / (mu * mv))) < 90;
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;
        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
